Author: Philip Withnall <pwithnall@gnome.org>
Date:   Tue Feb 18 16:44:58 2025 +0000

    gdatetime: Fix integer overflow when parsing very long ISO8601 inputs

    This will only happen with invalid (or maliciously invalid) potential
    ISO8601 strings, but `g_date_time_new_from_iso8601()` needs to be robust
    against that.

    Prevent `length` overflowing by correctly defining it as a `size_t`.
    Similarly for `date_length`, but additionally track its validity in a
    boolean rather than as its sign.

    Spotted by chamalsl as #YWH-PGM9867-43.

    Signed-off-by: Philip Withnall <pwithnall@gnome.org>

diff --git a/glib/gdatetime.c b/glib/gdatetime.c
index ad9c190b6..b33db2c20 100644
--- a/glib/gdatetime.c
+++ b/glib/gdatetime.c
@@ -1467,176 +1467,180 @@ parse_iso8601_time (const gchar *text, gsize length,
   /* Check for timezone suffix */
   *tz = parse_iso8601_timezone (text, length, &tz_offset);
   if (tz_offset >= 0)
     length = tz_offset;

   /* hh:mm:ss(.sss) */
   if (length >= 8 && text[2] == ':' && text[5] == ':')
     {
       return get_iso8601_int (text, 2, hour) &&
              get_iso8601_int (text + 3, 2, minute) &&
              get_iso8601_seconds (text + 6, length - 6, seconds);
     }
   /* hhmmss(.sss) */
   else if (length >= 6)
     {
       return get_iso8601_int (text, 2, hour) &&
              get_iso8601_int (text + 2, 2, minute) &&
              get_iso8601_seconds (text + 4, length - 4, seconds);
     }
   else
     return FALSE;
 }

 /**
  * g_date_time_new_from_iso8601: (constructor)
  * @text: an ISO 8601 formatted time string.
  * @default_tz: (nullable): a #GTimeZone to use if the text doesn't contain a
  *                          timezone, or %NULL.
  *
