Author: Philip Withnall <pwithnall@gnome.org>
Date:   Tue Feb 18 16:51:36 2025 +0000

    gdatetime: Fix potential integer overflow in timezone offset handling

    This one is much harder to trigger than the one in the previous commit,
    but mixing `gssize` and `gsize` always runs the risk of the former
    overflowing for very (very very) long input strings.

    Avoid that possibility by not using the sign of the `tz_offset` to
    indicate its validity, and instead using the return value of the
    function.

    Signed-off-by: Philip Withnall <pwithnall@gnome.org>

diff --git a/glib/gdatetime.c b/glib/gdatetime.c
index b33db2c20..792c2ed15 100644
--- a/glib/gdatetime.c
+++ b/glib/gdatetime.c
@@ -1316,234 +1316,236 @@ g_date_time_new_week (GTimeZone *tz, gint year, gint week, gint week_day, gint h
   if (ordinal_day < 0)
     {
       year--;
       ordinal_day += GREGORIAN_LEAP (year) ? 366 : 365;
     }
   else if (ordinal_day > (GREGORIAN_LEAP (year) ? 366 : 365))
     {
       ordinal_day -= (GREGORIAN_LEAP (year) ? 366 : 365);
       year++;
     }

   return g_date_time_new_ordinal (tz, year, ordinal_day, hour, minute, seconds);
 }

 static GDateTime *
 parse_iso8601_date (const gchar *text, gsize length,
                     gint hour, gint minute, gdouble seconds, GTimeZone *tz)
 {
   /* YYYY-MM-DD */
   if (length == 10 && text[4] == '-' && text[7] == '-')
     {
       int year, month, day;
       if (!get_iso8601_int (text, 4, &year) ||
           !get_iso8601_int (text + 5, 2, &month) ||
           !get_iso8601_int (text + 8, 2, &day))
         return NULL;
       return g_date_time_new (tz, year, month, day, hour, minute, seconds);
     }
   /* YYYY-DDD */
   else if (length == 8 && text[4] == '-')
     {
       gint year, ordinal_day;
       if (!get_iso8601_int (text, 4, &year) ||
           !get_iso8601_int (text + 5, 3, &ordinal_day))
         return NULL;
       return g_date_time_new_ordinal (tz, year, ordinal_day, hour, minute, seconds);
     }
   /* YYYY-Www-D */
   else if (length == 10 && text[4] == '-' && text[5] == 'W' && text[8] == '-')
     {
       gint year, week, week_day;
       if (!get_iso8601_int (text, 4, &year) ||
           !get_iso8601_int (text + 6, 2, &week) ||
           !get_iso8601_int (text + 9, 1, &week_day))
         return NULL;
       return g_date_time_new_week (tz, year, week, week_day, hour, minute, seconds);
     }
   /* YYYYWwwD */
   else if (length == 8 && text[4] == 'W')
     {
       gint year, week, week_day;
       if (!get_iso8601_int (text, 4, &year) ||
           !get_iso8601_int (text + 5, 2, &week) ||
           !get_iso8601_int (text + 7, 1, &week_day))
         return NULL;
       return g_date_time_new_week (tz, year, week, week_day, hour, minute, seconds);
     }
   /* YYYYMMDD */
   else if (length == 8)
     {
       int year, month, day;
       if (!get_iso8601_int (text, 4, &year) ||
           !get_iso8601_int (text + 4, 2, &month) ||
           !get_iso8601_int (text + 6, 2, &day))
         return NULL;
       return g_date_time_new (tz, year, month, day, hour, minute, seconds);
     }
   /* YYYYDDD */
   else if (length == 7)
     {
       gint year, ordinal_day;
       if (!get_iso8601_int (text, 4, &year) ||
           !get_iso8601_int (text + 4, 3, &ordinal_day))
         return NULL;
       return g_date_time_new_ordinal (tz, year, ordinal_day, hour, minute, seconds);
     }
   else
     return FALSE;
 }

